SELECT id, customer_id, order_date, amount, status, shipping_fee, SUM(amount) OVER (PARTITION BY customer_id ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, LAST_VALUE(amount) OVER (PARTITION BY status ORDER BY shipping_fee DESC, id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_amount FROM orders WHERE amount BETWEEN 690 AND 720;
